INSERT INTO public.corpus_findings (area, topic, claim, basis, confidence, sport, quantities) VALUES
  ('clinical', 'scope', 'A non-physician strength coach urges clients to challenge doctors'' supplement dismissals, including advising a cancer patient''s spouse and a sick athlete before medical appointments — an overreach into clinical decision-making.', 'experience', 'hedged', NULL, NULL),
  ('clinical', 'scope', 'The coach treats his own anecdotal supplement outcomes as more reliable than physicians'' evidence assessments, presenting personal experience as equivalent to clinical evidence.', 'experience', 'hedged', NULL, NULL),
  ('clinical', 'modifiers', 'Coach avoided high-volume, near-failure training for a detrained trainee (6 months off), citing rhabdomyolysis risk as low overall but meaningfully elevated for detrained individuals.', 'experience', 'hedged', NULL, '{"detraining_months":6}'::jsonb),
  ('clinical', 'modifiers', 'Recommended return-to-training approach after 6 months off: start light, train 3-4x/week, emphasize stretch-loaded eccentrics and reduced volume for 3-6 weeks before resuming prior training levels.', 'experience', 'moderate', NULL, '{"detraining_months":6,"frequency_per_week":"3-4","ramp_weeks":"3-6"}'::jsonb),
  ('clinical', 'stop_signs', 'Unilateral limb swelling with throbbing, tingling, or neurological change during a workout should prompt stopping immediately and urgent referral, since it can signal compartment syndrome, an arterial/venous clot, or thoracic outlet syndrome.', 'mechanistic', 'strong', NULL, NULL),
  ('clinical', 'stop_signs', 'Exertional chest tightness radiating to the arm plus palpitations still warrants same-day emergency evaluation even if symptoms fully resolve within about an hour of stopping activity.', 'cited_study', 'moderate', NULL, NULL),
  ('clinical', 'scope', 'A non-clinician''s correct response to a possibly dangerous symptom is recognizing the pattern and urging evaluation without alarming the person or naming a diagnosis, not attempting to diagnose it.', 'experience', 'strong', NULL, NULL),
  ('clinical', 'medications', 'A patient on a beta blocker (atenolol 100mg/day) reached only 93% of predicted max heart rate without symptoms on a stress test, illustrating how beta blockade blunts the exertional heart-rate response.', 'cited_study', 'hedged', NULL, '{"beta_blocker_dose_mg_per_day":100,"pct_predicted_max_hr":"93%"}'::jsonb),
  ('clinical', 'modifiers', 'A prior, cardiology-cleared, self-resolving atrial fibrillation episode is not treated as reason to categorically cut a trained athlete''s exercise volume; managing other risk factors is favored over deloading, per one host''s stated opinion.', 'experience', 'hedged', NULL, NULL),
  ('clinical', 'modifiers', 'Resistance training shows no meaningful association with increased atrial fibrillation risk in cited research, unlike very high-volume endurance training (roughly 4-5x standard guidelines, ~2000 lifetime hours).', 'cited_study', 'moderate', NULL, '{"endurance_volume_multiplier_vs_guidelines":"4-5x","training_hours_threshold":2000}'::jsonb),
  ('clinical', 'modifiers', 'Athletes who develop atrial fibrillation have lower stroke risk than non-athletes with atrial fibrillation in cited ski-cohort studies, though still higher than athletes without atrial fibrillation.', 'cited_study', 'moderate', NULL, '{"stroke_risk_increase_athletes_with_afib":"~2x","stroke_risk_increase_nonathletes_with_afib":"~4x"}'::jsonb),
  ('clinical', 'screening', 'Asymptomatic atrial fibrillation detected only via a consumer wearable lacks the evidence base of clinically diagnosed atrial fibrillation, so physicians describe its management as unresolved rather than protocolized.', 'experience', 'hedged', NULL, NULL),
  ('clinical', 'stop_signs', 'New, progressively worsening headaches that are worse in the morning, wake someone from sleep, and worsen with bending, coughing, or straining are treated as a red flag for elevated intracranial pressure needing urgent imaging, not a benign headache.', 'mechanistic', 'strong', NULL, NULL),
  ('clinical', 'stop_signs', 'Rapid unexplained weight gain of roughly 30-40 lb over months, despite unchanged diet and exercise, is treated as a medical red flag warranting endocrine/neurological workup rather than assumed nonadherence.', 'cited_study', 'moderate', NULL, '{"weight_gain_lb":"30-40","duration_months":7}'::jsonb),
  ('clinical', 'scope', 'When body composition changes despite consistent diet and exercise behavior, physicians frame this as outside a coach''s remit, requiring medical evaluation rather than a stricter training or diet program.', 'mechanistic', 'moderate', NULL, NULL),
  ('clinical', 'medications', 'Certain medications, psychiatric medications specifically named, are recognized as a cause of weight gain independent of training and diet adherence, and should be ruled out before attributing weight change to program compliance.', 'experience', 'moderate', NULL, NULL),
  ('clinical', 'screening', 'Wearable hypertension detection has low standalone screening sensitivity (about 41% overall, ~53% for the most severe cases) despite higher specificity, so it should not replace validated blood-pressure measurement.', 'cited_study', 'moderate', NULL, '{"sensitivity_overall_pct":41,"sensitivity_stage2_pct":54}'::jsonb),
  ('clinical', 'modifiers', 'A brief blood-pressure spike from heavy lifting is treated as clinically inconsequential, unlike sustained elevated resting blood pressure of the same magnitude, which these physicians do find concerning.', 'experience', 'moderate', NULL, NULL),
  ('clinical', 'screening', 'Hypertension decisions should rely on multi-day averaged home readings, not single measurements: a solitary elevated reading has only ~25% odds of reflecting a true change at 6 months, ~65% at 12 months.', 'cited_study', 'strong', NULL, '{"true_positive_prob_6mo_pct":25,"true_positive_prob_12mo_pct":65}'::jsonb),
  ('clinical', 'modifiers', 'Treatment aggressiveness for a given blood pressure reading should scale with cardiometabolic risk: identical BP numbers warrant less urgency in someone with no other risk factors than with diabetes, smoking, or obesity.', 'mechanistic', 'moderate', NULL, NULL),
  ('clinical', 'medications', 'Physicians caution that pushing blood pressure very low in older or neuropathic patients raises fall and injury risk, arguing against uniformly aggressive low targets in that population.', 'experience', 'moderate', NULL, NULL),
  ('clinical', 'scope', 'Resistant or disproportionately severe hypertension can signal a treatable secondary cause (e.g., primary aldosteronism, ~14% prevalence in primary-care hypertensives) needing physician lab testing, not something a coach could identify.', 'cited_study', 'strong', NULL, '{"secondary_cause_prevalence_pct":14}'::jsonb),
  ('clinical', 'medications', 'Chronic even mildly elevated blood pressure is framed as causing cumulative, largely asymptomatic organ damage (kidneys, eyes, heart) over years, motivating this source''s push for early pharmacological control rather than waiting on lifestyle change alone.', 'experience', 'moderate', NULL, NULL),
  ('clinical', 'medications', 'Once prescribed, blood-pressure medication should never be stopped or reduced except under the prescribing physician''s direction, even after major lifestyle-driven improvement.', 'experience', 'strong', NULL, NULL),
  ('clinical', 'modifiers', 'Hypertension can be primarily genetic rather than driven by body composition, so even lean, highly trained individuals may still require medication regardless of diet and training status.', 'experience', 'moderate', NULL, NULL),
  ('clinical', 'medications', 'Near-fainting or dizziness on standing after starting or adjusting a blood-pressure medication signals the dose may be too aggressive and should prompt physician-guided reduction, not self-adjustment.', 'experience', 'moderate', NULL, NULL),
  ('clinical', 'scope', 'This non-physician fitness educator frames all blood-pressure medication initiation, dosing, and discontinuation as decisions for the prescribing physician alone, explicitly outside his own coaching authority.', 'experience', 'strong', NULL, NULL),
  ('clinical', 'scope', 'Even a researcher advancing a non-mainstream cardiovascular-risk hypothesis stresses that participants should maintain their normal ongoing relationship with a treating physician rather than substitute the research for medical care.', 'experience', 'hedged', NULL, NULL),
  ('clinical', 'screening', 'A movement screen serves as a minimum-competency baseline check (e.g., ankle mobility, squat depth) before loading exercise, explicitly not a search for perfect movement or for dysfunction.', 'experience', 'moderate', NULL, NULL),
  ('clinical', 'screening', 'A greater than 10% side-to-side asymmetry in range of motion, speed, power, or strength is cited as a threshold associated with increased injury likelihood.', 'experience', 'strong', NULL, '{"asymmetry_threshold_pct":10}'::jsonb),
  ('clinical', 'pain', 'When screening or training uncovers pain (e.g., shoulder, knee), specific exercises are removed from the program rather than the entire program being halted.', 'experience', 'moderate', NULL, NULL),
  ('clinical', 'pain', 'Newly noticed pain when starting exercise after a sedentary period may reflect a pre-existing joint limitation that was symptom-free under daily activity but becomes symptomatic once loaded harder.', 'experience', 'hedged', NULL, NULL),
  ('clinical', 'screening', 'Conducting some baseline evaluation before writing a program is treated as a professional minimum, likened to a physician never prescribing treatment without history or examination.', 'experience', 'strong', NULL, NULL),
  ('clinical', 'modifiers', 'Sport-driven structural asymmetries (e.g., a throwing shoulder) are treated as expected, normal variants; attention instead goes to underlying mobility and motor-control prerequisites like neck, spine, and scapular control.', 'experience', 'moderate', NULL, NULL),
  ('clinical', 'modifiers', 'One coach describes returning to training after chemotherapy/radiation as needing a slow, staged restart with external oversight against overreaching, expecting roughly a year to regain prior capacity.', 'experience', 'hedged', NULL, NULL),
  ('clinical', 'modifiers', 'After a significant body-contouring surgery, several weeks of complete cessation from resistance training is expected, with lost muscle mass returning within about a month of resumed training, worst case six weeks.', 'experience', 'moderate', NULL, '{"no_training_weeks_range":"5-7","muscle_regain_typical_weeks":4,"muscle_regain_worst_case_weeks":6}'::jsonb),
  ('clinical', 'modifiers', 'Acute post-surgical recovery imposes site-specific movement restrictions (avoiding spinal flexion, limited sleep positions) to protect incisions, illustrating activity limits driven by the surgical site rather than blanket rest.', 'experience', 'moderate', NULL, NULL),
  ('clinical', 'stop_signs', 'Blunt chest trauma landing at a precise instant in the heart''s electrical repolarization cycle can trigger a life-threatening arrhythmia and cardiac arrest, a mechanism distinct from an ordinary hard hit.', 'mechanistic', 'strong', NULL, NULL),
  ('clinical', 'stop_signs', 'Collapse with absent breathing and heartbeat after chest impact is an emergency requiring immediate CPR, clearly distinct from transient breathlessness from an impact that resolves within moments.', 'experience', 'strong', NULL, NULL),
  ('clinical', 'scope', 'Managing a witnessed cardiac emergency required coordinated action from multiple medical and EMS personnel, not any single individual: true cardiac emergencies exceed one coach''s or trainer''s scope.', 'experience', 'strong', NULL, NULL),
  ('youth', 'safety', 'Claims that youth resistance training carries high injury risk lack evidentiary support; competitive weightlifting injury rates are extremely low, below youth football, soccer, and karate, though the cited rate reflects adult competitors, not children.', 'cited_study', 'moderate', NULL, '{"injury_rate_per_1000_participation_hours":0.0006}'::jsonb),
  ('youth', 'safety', 'Growth-plate injury requires a traumatic shearing force, not routine axial loading; plate closure is driven by long-term estrogen signaling rather than training-induced testosterone changes, so resistance training does not damage plates or stunt height.', 'mechanistic', 'strong', NULL, NULL),
  ('youth', 'safety', 'A child falling off their growth curve warrants a full medical workup for causes like malnutrition, chronic illness, or endocrine disorders; attributing it to squat training alone would be inappropriate clinical management.', 'experience', 'strong', NULL, NULL),
  ('youth', 'loading', 'Below mid-puberty (Tanner stage 3-4), strength gains come mainly from motor learning and neural adaptation rather than muscle growth, since low testosterone and androgen receptor density limit the muscle protein synthesis response to training.', 'mechanistic', 'moderate', NULL, NULL),
  ('youth', 'loading', 'For young kids (about 6-10), suggested progression starts with a very light bar held at the same load for one to three weeks until technique is clean, then micro-loading gradually, not standard linear progression.', 'experience', 'moderate', NULL, '{"hold_weeks":"1-3"}'::jsonb),
  ('youth', 'technique', 'Progression order for young beginners: teach squat, press, and pull as movement patterns with little to no load first to build motor control and balance, adding meaningful load only once movement quality is established.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'volume', 'Suggested youth frequency starts around twice weekly, progressing to three sessions a week over time, with 2-3 basic exercises per session limited mainly by a young child''s attention span, explicitly framed as experience, not evidence.', 'experience', 'hedged', NULL, '{"sessions_per_week_start":2,"sessions_per_week_progression":3,"exercises_per_session":"2-3"}'::jsonb),
  ('youth', 'maturity', 'Biological maturity (Tanner stage) rather than chronological age should guide training decisions; two same-age children at different Tanner stages are physiologically distinct and warrant different programming approaches.', 'mechanistic', 'strong', NULL, NULL),
  ('youth', 'loading', 'Overload training implements exceeding a young athlete''s strength capacity produce negative movement adaptations (e.g. collapsed bat path, compensatory patterns) instead of a positive training effect, rather than simply improving performance.', 'mechanistic', 'moderate', NULL, NULL),
  ('youth', 'technique', 'High-load, high-skill drills normally used with mature athletes are withheld from young teens because they lack sufficient strength to produce a positive adaptation from that load, reinforcing poor mechanics instead.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'loading', 'For rotational medicine-ball power work, roughly a 4-8 lb implement is recommended for young athletes, since the stimulus depends on moving the implement fast, not simply moving a heavy weight slowly.', 'experience', 'moderate', NULL, '{"medicine_ball_lbs_min":4,"medicine_ball_lbs_max":8}'::jsonb),
  ('youth', 'supervision', 'Complex multi-implement overload training systems are described as suited to older, more self-sufficient high-school-age athletes who can execute them without constant adult supervision, unlike younger kids who need that supervision.', 'experience', 'hedged', NULL, NULL),
  ('youth', 'maturity', 'Kids are described as biomechanically and neurologically distinct from adults, with immature coordination and body-position sense, given as the reason training tools and stimuli must be scaled for kids, not just downsized adult versions.', 'mechanistic', 'moderate', NULL, NULL),
  ('youth', 'safety', 'A cited study found UCL reconstruction (Tommy John) rates in baseball players aged 11-15 rose roughly sixfold between 2003 and 2014, coinciding with rising competitive game volume rather than resistance training.', 'cited_study', 'moderate', NULL, '{"ucl_reconstruction_increase_pct":669,"period":"2003-2014"}'::jsonb),
  ('youth', 'supervision', 'Cited survey data found more than two-thirds of youth coaches lack training in sport-specific tactics, general athletic development, and motivational coaching, describing widespread under-trained supervision as a systemic problem in youth sport.', 'cited_study', 'moderate', NULL, NULL),
  ('youth', 'technique', 'Recommended coach implementation order for a new team is to start with basic arm-care fundamentals in year one rather than complex interventions, adding complexity gradually rather than attempting everything at once.', 'experience', 'hedged', NULL, NULL),
  ('youth', 'supervision', 'For very young children (roughly ages 3-8), field position favors playful, low-structure facilitation over formal disciplinarian coaching, cautioning that imposing a rigid coach role too early can undermine engagement at that age.', 'experience', 'hedged', NULL, NULL),
  ('youth', 'mistakes', 'Prioritizing competitive win-loss outcomes over broad skill development at young ages is named as a driver of youth attrition; cited estimate is roughly 1.6-1.8 million kids quitting baseball annually.', 'cited_study', 'moderate', NULL, '{"annual_dropout_estimate":"1.6-1.8 million"}'::jsonb),
  ('youth', 'maturity', 'Anecdote-based position that a physically underdeveloped, low-skill young teen can become a highly competitive athlete within a few years if given continued developmental opportunity instead of being cut early for current skill level.', 'experience', 'hedged', NULL, NULL),
  ('youth', 'technique', 'Recommended session structure for youth (12-14) groups ends with a foundational bodyweight-strength block (squat, split squat, push-up, working toward chin-up, core) explicitly framed as not powerlifting, not early loaded lifting.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'technique', 'General progression model for teaching any movement to young athletes is position, then pattern, then performance: first the static hold/position, then a low-load dynamic pattern, only then a loaded or explosive version.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'volume', 'Warns youth multi-sport athletes can play more games in one summer month than a whole high school season (example: 25-30 in July versus about 22-25 all season), calling this an unrecoverable overload.', 'experience', 'strong', NULL, '{"games_july":"25-30","season_total_games":"22-25"}'::jsonb),
  ('youth', 'volume', 'For youth/teen athletes under heavy competition load, baseline recovery targets given are about 1g protein per lb bodyweight daily and roughly half bodyweight in fluid ounces of water, plus more in heat.', 'experience', 'moderate', NULL, '{"protein_g_per_lb_bw":1,"water_oz":"bodyweight/2 plus more in heat"}'::jsonb),
  ('youth', 'loading', 'Resisted sprint training (sled/prowler) for young or high-school athletes should use light-to-moderate loading, roughly a 10-25 lb plate, just enough to reinforce acceleration position rather than maximal loads.', 'experience', 'moderate', NULL, '{"sled_plate_lbs":"10-25"}'::jsonb),
  ('youth', 'mistakes', 'Names jumping straight to top-end/max-velocity sprint work without first building acceleration mechanics as a common mistake in youth speed training; acceleration should be drilled and established first.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'safety', 'ACL tear rates among youth athletes have risen sharply relative to prior decades; position attributes this primarily to early specialization and chronic under-recovery (poor sleep, hydration, nutrition, year-round single-sport training), not lack of prehab drills.', 'experience', 'strong', NULL, NULL),
  ('youth', 'safety', 'Canned ''ACL prevention'' programs (e.g. a few hip/balance exercises a few times weekly) are dismissed as insufficient alone; genuine injury reduction requires addressing foundational recovery (sleep, nutrition, hydration) first.', 'experience', 'strong', NULL, NULL),
  ('youth', 'mistakes', 'Youth athletes in structured, year-round single-sport programs are typically ''under-recovered'' rather than deconditioned: continuous training without an off-season leaves them chronically fatigued, poorly slept, and poorly hydrated or fed.', 'experience', 'strong', NULL, NULL),
  ('youth', 'volume', 'Baseline hydration guidance given for youth athletes is a minimum of half their bodyweight in ounces of water daily.', 'experience', 'moderate', NULL, '{"water_oz_min":"bodyweight/2"}'::jsonb),
  ('youth', 'loading', 'Youth strength programming should be progressive but non-linear and autoregulated: session content (e.g. dropping to mobility/recovery work) should adjust to the athlete''s presenting fatigue rather than following a fixed schedule regardless of readiness.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'mistakes', 'Early single-sport specialization before roughly middle school is explicitly discouraged; stated approach is sampling at least two sports and delaying club-level single-sport commitment until 8th grade or later to reduce burnout risk.', 'experience', 'strong', NULL, '{"delay_club_specialization_until_grade":8}'::jsonb),
  ('youth', 'mistakes', 'College recruiters reportedly do not weight highlight reels or club ranking for athletes as young as 11-14; pressuring kids to build a competitive ''brand'' that early is described as a misdirected priority.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'technique', 'Reaction time, rhythm, and balance/coordination training are named as commonly missing in today''s youth athletes (attributed to less unstructured outdoor play) and are prioritized alongside sport work partly because slow reactions force compensatory tissue overload.', 'mechanistic', 'moderate', NULL, NULL),
  ('youth', 'mistakes', 'Early single-sport specialization limits development of general athletic qualities; recommended model is broad multi-sport exposure in childhood (roughly 3 sports), narrowing over adolescence, with full specialization deferred to about age 17-18.', 'mechanistic', 'moderate', NULL, '{"specialization_age":"17-18"}'::jsonb),
  ('youth', 'safety', 'Loading the same tissues repetitively without variation during periods of rapid growth (peak height velocity) is linked to increased overuse-injury risk in young athletes.', 'mechanistic', 'moderate', NULL, NULL),
  ('youth', 'mistakes', 'Early specialization risks psychological burnout severe enough to cause permanent dropout from sport altogether, named as the most consequential downside of pushing single-sport focus on children.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'mistakes', 'Exceptions to the avoid-early-specialization rule exist for sports like gymnastics and diving that require peak performance at a young age, but these are linked to body-image issues, eating disorders, delayed maturation, and menstrual dysfunction.', 'mechanistic', 'moderate', NULL, NULL),
  ('youth', 'mistakes', 'Field position discourages parents and coaches from pressuring young athletes into specific sports or competitions, recommending the athlete self-select their sport through adolescence and prioritizing enjoyment and participation over results.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'mistakes', 'Overloading a training implement beyond a young athlete''s control capacity produces negative technique breakdown rather than performance gains — heavier is not automatically better for youth power-training tools.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'maturity', 'Youth athletes are described as physiologically and proprioceptively immature, not simply smaller adults, so training equipment and loading should match their actual capacities rather than be reduced adult standards.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'loading', 'For rotational power/throwing-style training, common youth guidance keeps implement weight light — roughly 4 to 8 pounds for medicine balls — because excess load prevents the fast movement speed the training targets.', 'experience', 'moderate', NULL, '{"medicine_ball_lb_min":4,"medicine_ball_lb_max":8}'::jsonb),
  ('youth', 'mistakes', 'Youth-level baseball should prioritize skill development over competitive results, with emphasis shifting toward competition only gradually as athletes progress, mirroring long-term athletic development models used across other sports.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'volume', 'After a break from throwing, workload should be rebuilt gradually rather than resumed at prior levels; described as standard onboarding practice to reduce injury risk in youth throwers.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'supervision', 'Some organizations require youth coaches to complete standardized training, such as concussion and injury-awareness protocols, before coaching — treating structured coach certification as necessary infrastructure rather than optional for youth programs.', 'experience', 'hedged', NULL, NULL),
  ('youth', 'loading', 'For a young athlete, spinal/axial loading is deliberately avoided early on; training instead builds base strength in the legs and hips through bodyweight and implement-based general preparation work first.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'technique', 'Plyometric and jump work for a young athlete progresses from low-amplitude landings to higher-amplitude jumps only after force-absorption and landing mechanics are established, rather than starting at full intensity.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'loading', 'Sled pushes and drags are used as a low-risk general-preparation tool to build strength, mobility, and endurance in a young athlete, positioned as an alternative to heavier barbell loading early on.', 'experience', 'hedged', NULL, NULL),
  ('youth', 'safety', 'Early training for a young athlete emphasizes eccentric strength and force-absorption/deceleration via low-level plyometrics before progressing to higher-force work, framed as building tendon resilience safely.', 'mechanistic', 'moderate', NULL, NULL),
  ('youth', 'loading', 'For roughly 13-14 year olds, early training deliberately does not prioritize maximal strength or load; body awareness and movement quality come first, with intensity increased gradually and without urgency.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'mistakes', 'Athletic-focused strength training for youth is explicitly distinguished from powerlifting; coaches criticize school weight-room cultures pushing kids toward weekly new personal-record max attempts as counterproductive to athletic development.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'technique', 'New movement skills are rehearsed slowly and under control first, then made faster and more forceful, and only then placed into reactive drills — echoing that technique must be grooved before near-maximal or fast lifting.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'safety', 'Teaching youth athletes an independent warm-up routine is framed partly as injury prevention: as kids get bigger and stronger through adolescence, skipping or rushing warm-up is described as how muscle strains happen.', 'experience', 'hedged', NULL, NULL),
  ('youth', 'technique', 'For younger or lower-level athletes, mobility work uses dynamic whole-body movement drills rather than prolonged static positional-breathing holds, which are reserved for older or more advanced athletes who can sustain the focus.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'maturity', 'Training approach is explicitly age-banded rather than uniform: roughly 13-18 year olds are coached as one group, while 6-9 and 10-12 year olds are treated as needing meaningfully different approaches.', 'experience', 'moderate', NULL, '{"age_bands":["6-9","10-12","13-18"]}'::jsonb),
  ('youth', 'volume', 'Game and competition density can outstrip recovery capacity even in youth athletes: performance testing showed a measurable drop after playing 8 basketball games in 4 days, used as a signal to back off.', 'experience', 'moderate', NULL, '{"games":8,"days":4}'::jsonb),
  ('youth', 'loading', 'For developing youth athletes, Olympic-lift derivatives are introduced only after a foundational strength base is built through basic squat, hinge, press, and pull work, and reserved for a tested propulsive-force deficit.', 'experience', 'hedged', NULL, NULL),
  ('youth', 'technique', 'Movement-efficiency work such as running and jumping mechanics is used as the first lever for improving a young athlete''s speed and jump height, explicitly sequenced before adding external load like weights.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'mistakes', 'States the goal for a young athlete is long-term career preparation rather than a fast two-to-three-month performance spike, explicitly rejecting high-intensity, heavy-load ''quick fix'' approaches for youth training.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'maturity', 'Whether an underload/overload bat-speed tool suits an older youth hitter depends more on training age and biological age than on chronological age.', 'experience', 'hedged', NULL, NULL),
  ('youth', 'volume', 'Four days per week of highly structured, focused practice is floated as a workable ceiling for high-school-age athletes, citing overtraining risk and the need for a mental break.', 'experience', 'hedged', NULL, NULL),
  ('youth', 'technique', 'Youth sprint mechanics flaws are attributed to insufficient strength rather than poor motor patterning, since athletes lack the strength to execute proper front/backside mechanics.', 'mechanistic', 'strong', NULL, NULL),
  ('youth', 'loading', 'For 4-5 year olds, loading should stay bodyweight only (squats, lunges); external load is introduced later via goblet squats/lunges and pistol squats before eventual barbell back-loading as the athlete ages.', 'experience', 'moderate', NULL, '{"progression":"bodyweight -> goblet squat/lunge, pistol squat -> barbell back load"}'::jsonb),
  ('youth', 'volume', 'Low-level plyometrics (pogo hops, basic jump variations) are prescribed 3-4 sessions per week for young athletes, kept at low intensity rather than advanced box-jump variations.', 'experience', 'moderate', NULL, '{"frequency":"3-4x/week"}'::jsonb),
  ('youth', 'volume', 'Power skips and bounds for height and distance are recommended three times per week to build elastic strength in young athletes, alongside strength work.', 'experience', 'moderate', NULL, '{"frequency":"3x/week"}'::jsonb),
  ('youth', 'loading', 'Resisted sprint work (sled push/pull) should vary between heavy and light loads across sessions rather than one fixed load, with no stated minimum age or load ceiling.', 'experience', 'hedged', NULL, NULL),
  ('youth', 'technique', 'Youth speed gains are attributed to accumulating years of high-velocity sprint volume rather than direct technical cueing of sprint mechanics.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'technique', 'Mechanical/technical coaching is withheld as a prerequisite-gated intervention, introduced only once an athlete already shows adequate relative and absolute strength.', 'experience', 'strong', NULL, NULL),
  ('youth', 'loading', 'For a 12-year-old single-sport athlete, training emphasis is placed on joint integrity, movement quality, and body awareness with only low-level plyometrics, not maximal loading.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'mistakes', 'General multi-directional movement competency should be built into an already sport-specialized young athlete before further sport-specific progression, to head off compensation patterns.', 'experience', 'moderate', NULL, NULL),
  ('youth', 'safety', 'A young athlete who has only ever trained in one sport is treated as a risk case for movement compensation, motivating general athletic work before further specialization.', 'experience', 'hedged', NULL, NULL),
  ('youth', 'maturity', 'Young athletes are defined as roughly age 8 until the onset of puberty (about 12-14, earlier in girls), the window this framework targets.', 'experience', 'moderate', NULL, '{"age_range_years":"8 to ~12-14"}'::jsonb),
  ('youth', 'loading', 'Structured strength and conditioning is not essential for the 8-to-prepuberty age group; multi-sport play alone provides benefit, so any added training should stay general, not sport-specific.', 'experience', 'strong', NULL, NULL),
  ('youth', 'volume', 'Training for this age group should not follow a strict long-term periodized structure aimed at peaking for a season; enjoyment is prioritized over structured progression.', 'experience', 'strong', NULL, NULL),
  ('youth', 'loading', 'External loading for primary movement patterns (squat, hinge, push, pull, rotate) should stay light and high-rep, in the 8-14 rep range, introduced only after bodyweight competency.', 'experience', 'moderate', NULL, '{"reps":"8-14"}'::jsonb),
  ('youth', 'technique', 'Body awareness and proprioception via bodyweight movement should be established before any additional external loading is introduced for young athletes.', 'experience', 'strong', NULL, NULL),
  ('youth', 'volume', 'Conditioning for this age group should be delivered through circuits, intervals, and small games rather than structured endurance training, to keep effort high while staying enjoyable.', 'experience', 'moderate', NULL, NULL),
  ('masters', 'hormonal', 'Menopause shifts fat storage from hips/thighs toward visceral abdominal fat as estrogen falls, changing body composition risk independent of total scale weight.', 'cited_study', 'strong', NULL, NULL),
  ('masters', 'decline', 'Cohort data attributes only a small fraction of midlife weight change to menopause itself (about 1.5kg fat gain, 0.2kg lean loss over 3.5 years); most midlife weight gain is decades of small behavior drift.', 'cited_study', 'strong', NULL, '{"fat_gain_kg":1.5,"lean_loss_kg":0.2,"period_years":3.5}'::jsonb),
  ('masters', 'decline', 'Menopause accounts for only roughly 15-25% of midlife joint pain; the rest is age/osteoarthritis-driven and worsened by inactivity, similar to same-age men.', 'cited_study', 'moderate', NULL, '{"menopause_attributable_share_pct":"15-25"}'::jsonb),
  ('masters', 'decline', 'Genitourinary tissue changes from menopause do not resolve spontaneously and worsen progressively without treatment, unlike most other menopause-linked symptoms which stabilize or improve.', 'cited_study', 'strong', NULL, NULL),
  ('masters', 'retained', 'Menopause-related brain fog and cognitive complaints are typically small in magnitude and reversible within a few years, and are mostly downstream of poor sleep and mood rather than direct hormonal effects on the brain.', 'cited_study', 'moderate', NULL, NULL),
  ('masters', 'retained', 'A randomized trial found postmenopausal women gain muscle from 12 weeks of resistance training regardless of hormone status (placebo ~4% quad CSA gain, estradiol patch ~8%); training drives the adaptation, estrogen only amplifies it.', 'cited_study', 'strong', NULL, '{"placebo_gain_pct":4,"estradiol_gain_pct":8,"duration_weeks":12}'::jsonb),
  ('masters', 'hormonal', 'A meta-analysis of 23 studies (~9,000 women) found menopausal hormone therapy adds only a modest ~5% average strength advantage on top of resistance training, not a substitute for it.', 'cited_study', 'strong', NULL, '{"studies":23,"n_women":9000,"strength_advantage_pct":5}'::jsonb),
  ('masters', 'hormonal', 'Exercise alone is not an effective primary treatment for hot flashes: guidance does not recommend it as first-line vasomotor therapy, and evidence shows it slightly reduces severity but not frequency.', 'cited_study', 'strong', NULL, NULL),
  ('masters', 'hormonal', 'A meta-analysis of 36 trials (8,000+ women) found no real benefit of testosterone supplementation on body composition, muscle, or bone in women; measurable effects appear only at supraphysiological, PED-level doses.', 'cited_study', 'strong', NULL, '{"trials":36,"n_women":8000}'::jsonb),
  ('masters', 'hormonal', 'The biological case for menopause-specific training protocols (accelerated visceral fat, accelerated lean loss, reduced anabolic sensitivity) is real but modest and time-limited, arguing against needing a fundamentally different programming paradigm.', 'cited_study', 'moderate', NULL, NULL),
  ('masters', 'decline', 'Masters powerlifting scoring layers an age-adjustment multiplier on top of a bodyweight-adjusted score, scaling up by roughly one to a few percent per year past 40, formalizing expected age-related strength decline.', 'experience', 'hedged', NULL, '{"example_age":53,"example_multiplier_approx":1.07}'::jsonb),
  ('masters', 'retained', 'A 53-year-old competitive lifter hit near-lifetime-best results (180kg squat, ~115kg bench, 227.5kg deadlift at 73.5kg bodyweight), showing heavy near-maximal competitive loading stays achievable well into the 50s with continued training.', 'experience', 'hedged', NULL, '{"age":53,"bodyweight_kg":73.55,"squat_kg":180,"bench_kg":115,"deadlift_kg":227.5}'::jsonb),
  ('masters', 'decline', 'Power and rate of force development, not maximal strength, is the first physical quality to decline with age, per a principle attributed to an exercise-science mentor.', 'mechanistic', 'moderate', NULL, NULL),
  ('masters', 'recovery', 'Recovery capacity declines meaningfully past 40, prompting a shift from standard 3-weeks-on/1-off blocks to more frequent deloads, e.g. two heavy weeks then one lighter week within six-week cycles.', 'experience', 'moderate', NULL, '{"block_pattern":"2 heavy weeks + 1 light week per 6-week cycle"}'::jsonb),
  ('masters', 'intensity', 'Once high strength/power output is established, older lifters need not push a new near-maximal top set every session; instead periodically retest peak loads (e.g. every couple months) while training sub-maximally otherwise.', 'experience', 'moderate', NULL, '{"retest_frequency":"every couple months"}'::jsonb),
  ('masters', 'intensity', 'Heavy loading remains appropriate past 40 and should not be abandoned; strength/muscle already built should be periodically maintained with heavier blocks rather than trained away from entirely.', 'experience', 'moderate', NULL, NULL),
  ('masters', 'power', 'Speed and power training should continue past 40 but must be reintroduced via regressed, lower-force progressions (band-assisted jumps, medicine-ball throws) rather than resumed at prior maximal-effort levels after a lapse.', 'experience', 'moderate', NULL, NULL),
  ('masters', 'recovery', 'Mobility work should scale up with age by a rule of thumb of roughly one dedicated session per week for each decade of life, meaning over-40 lifters should address it nearly daily.', 'experience', 'hedged', NULL, '{"heuristic":"~1 session/week per decade of age"}'::jsonb),
  ('masters', 'selection', 'Older lifters should rotate training emphasis across the year in quarterly blocks (mobility, fat loss, athleticism, strength) rather than pursuing one quality year-round, to avoid losing untrained qualities.', 'experience', 'moderate', NULL, NULL),
  ('masters', 'selection', 'For lower-body exercise selection with age, training should rotate through bilateral symmetric, split/offset, and single-leg stances over a training year rather than relying only on bilateral squat/hinge patterns.', 'experience', 'moderate', NULL, NULL),
  ('masters', 'decline', 'Selective death of alpha motor neurons serving fast-twitch fibers explains why power declines fastest, then strength, then muscle size; by roughly age 70 up to half the motor neurons present at 20 may be gone.', 'mechanistic', 'strong', NULL, '{"motor_neuron_loss_pct_by_age_70":"25-50"}'::jsonb),
  ('masters', 'decline', 'In a cited powerlifting study, men over 69 lost strength at only about 0.35%/year versus about 1%/year in the general population, and women over 59 who kept competing gained 2.5-5% strength per year.', 'cited_study', 'strong', NULL, '{"powerlifter_men_over_69_decline_pct_per_year":0.35,"general_pop_decline_pct_per_year":1,"powerlifter_women_over_59_gain_pct_per_year":"2.5-5"}'::jsonb),
  ('masters', 'retained', 'Muscle retains real plasticity into old age: even people in their 90s can get measurably stronger with resistance training, so chronological age alone does not cap trainability.', 'mechanistic', 'strong', NULL, NULL),
  ('masters', 'recovery', 'Anabolic resistance (blunted muscle-protein-synthesis response to training or protein, common in older or multimorbid people) is reversible by raising per-session training volume/intensity and per-meal protein to roughly 30-40g rather than 10-20g.', 'mechanistic', 'strong', NULL, '{"effective_protein_per_meal_g":"30-40","ineffective_protein_per_meal_g":"10-20"}'::jsonb),
  ('masters', 'recovery', 'For people already sarcopenic or at risk, training should start at lower volume than general guidelines because they''re more deconditioning-vulnerable, then increase gradually; underloading them is judged the bigger risk, not injury.', 'experience', 'moderate', NULL, NULL),
  ('masters', 'intensity', 'Heavy resistance training is argued safe and appropriate past 60: cited injury rates of about 2-4 per 1000 lifting hours resemble cycling or walking, and most injuries resolve within roughly two weeks.', 'cited_study', 'strong', NULL, '{"injury_rate_per_1000_participation_hours":"2-4"}'::jsonb),
  ('masters', 'power', 'Programming for older or at-risk adults should combine low-velocity strength work with high-velocity power training, since power/explosive capacity, not maximal strength alone, governs the ability to catch a fall.', 'mechanistic', 'moderate', NULL, NULL),
  ('masters', 'hormonal', 'Testosterone replacement in deficient older adults increases muscle mass but does not by itself improve gait speed or physical-performance scores without concurrent exercise; mechanical loading, not hormone status, drives functional improvement.', 'mechanistic', 'strong', NULL, NULL),
  ('masters', 'recovery', 'One speaker (mid-40s) reports sleeping under about 7 hours visibly degrades explosive, speed-based lifts and reaction time more than it degrades plain maximal-strength performance, based on personal experience.', 'experience', 'hedged', NULL, '{"sleep_threshold_hours":7}'::jsonb),
  ('masters', 'power', 'A speaker''s maximal sprint attempt in his mid-40s after years without sprinting caused a hip-flexor strain, framed as a deconditioning risk from unpracticed high-velocity movement rather than a fixed age-related power ceiling.', 'experience', 'moderate', NULL, NULL),
  ('masters', 'power', 'Aging athletes describe needing a longer, more deliberate warm-up and gradual buildup before explosive efforts like sprinting or jumping in their 30s-40s, versus being able to go straight into them when younger.', 'experience', 'hedged', NULL, NULL),
  ('masters', 'retained', 'Speakers cite an unverified secondhand graph suggesting lifelong trained individuals keep near-peak functional quality of life until their 60s-70s, while untrained peers'' function starts declining from the mid-40s to early 50s.', 'experience', 'hedged', NULL, NULL),
  ('masters', 'recovery', 'Years of accumulated heavy-training injuries are described as a cumulative training-load effect distinct from calendar age, prompting increased emphasis on mobility and joint-care work as training years accumulate.', 'experience', 'hedged', NULL, NULL),
  ('masters', 'hormonal', 'Estrogen acts as an anti-catabolic shield limiting apoptosis in muscle and bone and preserving satellite-cell function, while testosterone is more directly anabolic; menopause is estrogen withdrawal layered on already-declining testosterone.', 'mechanistic', 'strong', NULL, NULL),
  ('masters', 'decline', 'Around the menopausal transition, muscle quality (strength/power per unit mass) drops faster than muscle size, mirroring sarcopenia; jump power and grip strength decline measurably even when lean mass barely changes.', 'mechanistic', 'moderate', NULL, NULL),
  ('masters', 'retained', 'Despite low estrogen and already-low testosterone, postmenopausal women on a real resistance program gain strength and muscle at the same rate as premenopausal women; mechanical loading is argued to override the hormonal deficit.', 'mechanistic', 'strong', NULL, NULL),
  ('masters', 'hormonal', 'Postmenopausal women show exaggerated satellite (stem) cell recruitment in response to heavy resistance training compared with younger trained women, framed as compensation for a lower baseline regenerative environment.', 'mechanistic', 'moderate', NULL, NULL),
  ('masters', 'hormonal', 'A cited 2021 trial found postmenopausal women resistance training alone gained about 4% quadriceps cross-sectional area, versus about 8% when combined with menopausal hormone therapy; hormones amplify but don''t replace training.', 'cited_study', 'strong', NULL, '{"RT_only_quad_CSA_gain_pct":4,"RT_plus_MHT_quad_CSA_gain_pct":8}'::jsonb),
  ('masters', 'hormonal', 'The recommended program for peri/postmenopausal women is the same as for any healthy adult: about twice-weekly compound resistance training at 60-80% of 1RM plus 150-300 minutes weekly moderate cardio; no menopause-specific plan is needed.', 'mechanistic', 'strong', NULL, '{"RT_sessions_per_week":2,"intensity_pct_1RM":"60-80","moderate_cardio_min_per_week":"150-300"}'::jsonb),
  ('masters', 'recovery', 'A cited 2022 trial found twice-weekly training had a higher non-response rate than three-times-weekly in postmenopausal women, but this is attributed to lower total training volume rather than frequency itself, and isn''t menopause-specific.', 'cited_study', 'moderate', NULL, NULL),
  ('masters', 'hormonal', 'Insulin resistance predicts non-response to resistance training in postmenopausal women; each one-unit HOMA-IR increase was linked to about 40% higher odds of non-response, a pattern also seen in older adults and diabetes generally.', 'cited_study', 'strong', NULL, '{"nonresponse_odds_increase_pct_per_HOMA_IR_unit":40}'::jsonb),
  ('masters', 'power', 'Explosive, high-intent movements like the pump snatch and skips are recommended weekly for men over 40 to preserve coordination and athleticism, with jump/landing capability described as linked to longevity and lean mass.', 'experience', 'hedged', NULL, NULL),
  ('masters', 'hormonal', 'Heavy compound lifts like the deadlift may raise testosterone acutely the next day, but chronic testosterone benefit is attributed to building lean mass, lowering body-fat inflammation, and reducing stress, not the acute spike.', 'experience', 'hedged', NULL, NULL),
  ('masters', 'intensity', 'Recommends heavy deadlifting only once weekly with undulating load (alternating a heavier low-rep week and a lighter higher-rep week) rather than maximal effort every session for a man training in his 40s.', 'experience', 'hedged', NULL, '{"deadlift_frequency_per_week":1}'::jsonb),
  ('masters', 'retained', 'Offers strength benchmarks framed as achievable for men training in their 40s-50s (back squat 1.5x bodyweight progressing to 1.75x, and 10 dead-hang pull-ups), pushing back against treating age as an excuse.', 'experience', 'hedged', NULL, '{"back_squat_bodyweight_multiple":"1.5-1.75","pullup_goal_reps":10}'::jsonb),
  ('masters', 'power', 'Recommends weekly sprint and plyometric work (hill sprints starting around 50-60% effort, pogo-hop jumps), explicitly framed as important with age for maintaining explosiveness, progressing intensity based on how the body responds.', 'experience', 'hedged', NULL, NULL),
  ('female', 'cycle', 'Rodent ovariectomy models suggesting estradiol is anabolic don''t replicate in humans; hormone-tracked within-subject studies find similar muscle protein synthesis and breakdown in high-estradiol and high-progesterone phases.', 'cited_study', 'moderate', NULL, NULL),
  ('female', 'cycle', 'Earlier menstrual-cycle training studies attributed outcomes to estradiol or progesterone despite never measuring hormones or confirming ovulation, undermining their conclusions.', 'cited_study', 'moderate', NULL, NULL),
  ('female', 'cycle', 'No high-quality human evidence shows phase-based training or nutrition prescription improves hypertrophy, strength, or body-composition outcomes versus autoregulating to daily symptoms.', 'cited_study', 'hedged', NULL, NULL),
  ('female', 'cycle', 'Estrogen-based hormone therapy after menopause doesn''t appear to prevent muscle loss, weakening the mechanistic case that estradiol fluctuations drive training-relevant muscle changes.', 'cited_study', 'moderate', NULL, NULL),
  ('female', 'no_difference', 'When studies on muscle growth, rep ranges, and fat loss originally conducted in men are repeated in women, outcomes replicate; sex is not a driver of programming differences.', 'cited_study', 'moderate', NULL, NULL),
  ('female', 'no_difference', 'Fiber-type composition differs by sex, but because fiber-type and molecular adaptations are driven by the training stimulus rather than a fixed baseline, this doesn''t justify sex-specific programming.', 'mechanistic', 'moderate', NULL, NULL),
  ('female', 'no_difference', 'Controlled trials of regular fasted training over 6 to 12 weeks show no differences in fat mass, lean mass, or strength changes; no evidence suggests effects differ by sex.', 'cited_study', 'moderate', NULL, '{"duration_weeks":"6-12"}'::jsonb),
  ('female', 'no_difference', 'Recommended protein intake while cutting, about 1.0 to 1.2 grams per pound of bodyweight, is applied with the same formula to male and female examples, scaled only by body weight.', 'experience', 'moderate', NULL, '{"protein_g_per_lb":"1.0-1.2"}'::jsonb),
  ('female', 'no_difference', 'Coaches report training programming isn''t meaningfully different by sex; muscle adapts the same way regardless of gender, and adjustments stem from individual recovery and response, not sex.', 'experience', 'moderate', NULL, NULL),
  ('female', 'cycle', 'A coach who initially adjusted programming around an athlete''s menstrual cycle later decided this was not good practice, and now treats male and female athletes the same by default.', 'experience', 'hedged', NULL, NULL),
  ('female', 'cycle', 'Estrogen dominance in the first half of the cycle is framed as supporting muscle recovery, glucose handling, and stress resilience, making it a better window for higher-intensity work.', 'mechanistic', 'hedged', NULL, NULL),
  ('female', 'cycle', 'Rising progesterone in the second half of the cycle is said to raise body temperature and perceived exertion, so an unchanged load can feel far harder without reflecting real strength loss.', 'mechanistic', 'hedged', NULL, NULL),
  ('female', 'cycle', 'Recommends undulating intensity to the cycle: push harder in the first half, prioritize recovery (not full rest) in the second half, individualized to how the athlete feels.', 'experience', 'hedged', NULL, NULL),
  ('female', 'cycle', 'Explicitly rejects popular cycle-syncing advice that prescribes only walking or yoga for a full week during the luteal phase, arguing that produces no training adaptation.', 'experience', 'hedged', NULL, NULL),
  ('female', 'cycle', 'Cites a sports-medicine meta-analysis finding a statistically significant but very small performance decrease in the early follicular phase (menstruation onset), with effect sizes around 0.1-0.14 (small by Cohen''s d).', 'cited_study', 'moderate', NULL, '{"effect_size_cohens_d":"0.1-0.14"}'::jsonb),
  ('female', 'cycle', 'Argues that because the population-level cycle effect on performance is trivial, broad recommendations to reduce training intensity based on cycle phase are not well justified.', 'cited_study', 'moderate', NULL, NULL),
  ('female', 'no_difference', 'Recommends adjusting training based on individual symptoms and how a session feels, not on menstrual cycle phase itself, since most people won''t be hit hard enough to need it.', 'cited_study', 'moderate', NULL, NULL),
  ('female', 'cycle', 'An 1877 Harvard-prize-winning study tracking pulse, blood pressure, and strength across the cycle in roughly 268 women found no physiological basis for requiring rest during menstruation.', 'cited_study', 'hedged', NULL, '{"year":1877,"survey_n":268}'::jsonb),
  ('female', 'cycle', 'Cites a modern research line (Colenso-Semple et al.) concluding cycle phase does not meaningfully change how muscle responds to training, and that the broader literature shows no reliable phase effect on strength.', 'cited_study', 'moderate', NULL, NULL),
  ('female', 'no_difference', 'Frames historical medical bans on women''s vigorous exercise (fixed energy-reserve theory, fears of masculinization, infertility, or organ displacement) as scientifically unfounded relative to current evidence.', 'cited_study', 'moderate', NULL, NULL),
  ('female', 'no_difference', 'Cites a controlled trial where postmenopausal women with low bone mass did heavy loading (5 reps near 85% of 1RM, twice weekly, 8 months) and gained lumbar bone density with minimal injury.', 'cited_study', 'moderate', NULL, '{"lumbar_bmd_change_pct":2.9,"control_change_pct":-1.2,"duration_months":8,"sessions_per_week":2,"reps":5,"intensity_pct_1rm":85,"injuries":1,"supervised_sessions":">2600"}'::jsonb),
  ('female', 'perinatal', 'Notes 1985 pregnancy exercise guidance capped heart rate and session length very conservatively and took decades to loosen toward endorsing strength training, implying early restrictions were overly cautious.', 'cited_study', 'hedged', NULL, '{"year":1985,"max_heart_rate_bpm":140,"session_duration_min":15}'::jsonb),
  ('female', 'distribution', 'Argues female athletes are commonly underloaded relative to true capacity, and generic light injury-prevention drills are a poor substitute for genuine heavy strength and power training.', 'experience', 'hedged', NULL, NULL),
  ('female', 'distribution', 'Cites research attributed to an ACL researcher (Hewett) that year-round strength training just one to two times weekly can cut female athletes'' ACL injury risk by roughly 50%.', 'cited_study', 'moderate', NULL, '{"acl_risk_reduction_pct":50,"sessions_per_week":"1-2"}'::jsonb),
  ('female', 'distribution', 'Argues upper-body strength work (e.g., pull-ups) is undervalued and resisted by female soccer athletes despite benefiting posture and running mechanics, cautioning against skewing programming to lower body only.', 'experience', 'hedged', NULL, NULL),
  ('female', 'fatigue', 'Flags a missed period lasting several months as a serious red flag for chronic underfueling or overtraining in female athletes, warranting referral to a doctor or dietitian.', 'experience', 'moderate', NULL, NULL),
  ('female', 'fatigue', 'States unintentional or intentional undereating is common among female athletes and impairs recovery and muscle gain, leaving them in a chronic fatigue state that raises injury risk.', 'experience', 'hedged', NULL, NULL),
  ('female', 'cycle', 'Practitioner explicitly opposes training around the menstrual cycle (e.g., backing off to yoga in the luteal phase), arguing consistency drives better adaptations and citing its popularization by a national team as unfounded.', 'experience', 'hedged', NULL, NULL),
  ('detraining', 'return_prescription', 'A short training layoff may temporarily increase sensitivity to the training stimulus, similar to post-deload or novice responsiveness, potentially producing faster initial regains on return.', 'experience', 'hedged', NULL, NULL),
  ('detraining', 'by_training_age', 'Detraining research on complete cessation mostly studies untrained novices, since trained lifters won''t volunteer for months of total inactivity, so it likely overstates losses for trained lifters doing any modified training.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'loss_rate', 'Even in studies of complete training cessation among untrained subjects, only a modest decrease in size and strength occurs, implying trained lifters doing partial training during a break lose even less.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'retention', 'A protective repeated-bout effect reduces muscle damage and soreness on return; even contractions at about 10% of maximal voluntary force are enough to trigger it before loads ramp up.', 'cited_study', 'strong', NULL, '{"mvc_threshold_percent":10}'::jsonb),
  ('detraining', 'return_prescription', 'When resuming after a layoff, undershoot rather than overshoot volume and load: undershooting still yields the protective repeated-bout adaptation, while overshooting raises fatigue, soreness, and hurts near-term performance.', 'mechanistic', 'strong', NULL, NULL),
  ('detraining', 'return_prescription', 'Expected time to match or exceed pre-layoff performance is roughly equal to the layoff''s length, based on novice complete-cessation studies; experienced lifters doing modified training can likely return faster.', 'experience', 'moderate', NULL, '{"return_duration_ratio_to_layoff":1.0}'::jsonb),
  ('detraining', 'retention', 'Skill and strength regained after a break come back faster than they took to originally build, a protective carryover from prior training experience analogous to relearning a long-unused motor skill.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'soreness', 'On return from a layoff, lower strength, size, neural adaptation, skill, and endurance combine with a sudden workload spike to raise susceptibility to muscle damage, fatigue, and injury.', 'mechanistic', 'strong', NULL, NULL),
  ('detraining', 'return_prescription', 'Injury risk follows a bell curve with rate of workload increase: ramping load too fast after a break raises injury risk, but resuming too little or too slowly also raises it.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'Safe return volume should be set by balancing training load (volume, RPE, frequency) against current recovery capacity (sleep, nutrition, stress), not by a fixed schedule.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'soreness', 'Under a graded-exposure/tissue-tolerance model, capacity for load must rebuild gradually after detraining; pushing straight into a large overload risks tissue failure instead of adaptation.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'by_training_age', 'Current training age/fitness level is named as one of the direct risk factors for injury on return, alongside prior injury history and recent spikes in workload.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'retention', 'Regaining previously built muscle after a layoff is markedly faster than the original hypertrophy, historically explained by persistent neural and motor-learning adaptations from the earlier training period.', 'mechanistic', 'strong', NULL, NULL),
  ('detraining', 'retention', 'A 2010 rodent study found nuclei added to muscle fibers during growth are protected from the cell loss seen in atrophy, letting retraining skip new-nuclei recruitment and regrow muscle faster.', 'cited_study', 'strong', NULL, NULL),
  ('detraining', 'retention', 'A human study training 7 weeks, stopping 7 weeks, then retraining 7 weeks found DNA-level changes from the first block persisted through the break and may last years.', 'cited_study', 'moderate', NULL, '{"training_weeks":7,"detraining_weeks":7,"retraining_weeks":7}'::jsonb),
  ('detraining', 'maintenance', 'A study comparing 24 weeks continuous training to periodic training (six-week blocks separated by three-week breaks) found triceps and pec hypertrophy ended equal despite more fluctuation in the periodic group.', 'cited_study', 'strong', NULL, '{"total_weeks":24,"training_block_weeks":6,"break_weeks":3}'::jsonb),
  ('detraining', 'return_prescription', 'Impressive gains from a program run right after a long layoff are inflated by muscle memory; judge a program''s real effectiveness against a lifter''s typical progressive-training baseline instead.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'loss_rate', 'For a break longer than a week, substituting bodyweight activity for barbell training is unlikely to meaningfully preserve squat/bench/deadlift/press numbers, though it beats complete inactivity.', 'experience', 'moderate', NULL, '{"break_definition_weeks":1}'::jsonb),
  ('detraining', 'retention', 'During a layoff, muscle cross-sectional area shrinks but contractile machinery and myonuclei number persist, so muscle rapidly re-expands toward baseline on retraining, the physiological basis of muscle memory.', 'mechanistic', 'strong', NULL, NULL),
  ('detraining', 'return_prescription', 'After about three weeks with no squat, bench, deadlift, or press training, a lifter likely won''t hit prior peak loads immediately, but strength is expected to recover fairly quickly.', 'experience', 'moderate', NULL, '{"layoff_weeks":3}'::jsonb),
  ('detraining', 'return_prescription', 'Don''t taper training volume before a planned break unless already peaking; cutting volume right before departure effectively starts the detraining process early.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'maintenance', 'Maintenance volume needed to hold strength during a break is highly individual: training-sensitive lifters can go weeks with little to no training and still perform near their prior working weight.', 'experience', 'moderate', NULL, '{"example_no_squat_weeks":6}'::jsonb),
  ('detraining', 'return_prescription', 'Movement skill and technique degrade faster than raw strength after a short layoff, so a lift feeling technically off on return may reflect skill loss, not true strength loss.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'There is no fixed formula to prevent tendinopathy on return; avoid repeating the same fatigue pattern and frequency that previously triggered symptoms in that individual by varying exercise or volume.', 'experience', 'hedged', NULL, NULL),
  ('detraining', 'loss_rate', 'Muscle atrophy begins almost immediately once training stops and accumulates progressively with time off: one to two weeks produces minimal loss while multiple months produces significant loss.', 'mechanistic', 'strong', NULL, NULL),
  ('detraining', 'loss_rate', 'An 8-week complete bed-rest study showed quadriceps size decreasing progressively across the intervention, an extreme case illustrating continuous muscle loss without any exercise stimulus.', 'cited_study', 'moderate', NULL, '{"bed_rest_weeks":8}'::jsonb),
  ('detraining', 'retention', 'A study training the quads for 10 weeks, detraining 20 weeks, then retraining 5 weeks found quad size returned to and exceeded its prior peak within that 5-week retraining period.', 'cited_study', 'strong', NULL, '{"initial_training_weeks":10,"detraining_weeks":20,"retraining_weeks":5}'::jsonb),
  ('detraining', 'retention', 'The myonuclear domain theory holds that nuclei added during muscle growth persist even as fibers shrink in detraining, giving trained muscle a higher nuclei-to-size ratio that speeds regrowth.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'maintenance', 'Using minimum-effective-dose strength research as a proxy, roughly 2-3 sets per muscle group weekly, taken close to failure, is estimated sufficient to maintain most or all muscle mass short-term.', 'cited_study', 'moderate', NULL, '{"maintenance_sets_per_muscle_per_week":"2-3","reps_per_set":"6-12"}'::jsonb),
  ('detraining', 'maintenance', 'A 6-month bench-press study found an intermittent schedule (six weeks training, three weeks off, repeated) dipped in chest size during off-weeks but ended with growth roughly equal to continuous training.', 'cited_study', 'strong', NULL, '{"total_months":6,"training_block_weeks":6,"break_weeks":3}'::jsonb),
  ('detraining', 'loss_rate', 'Detraining severity depends mainly on why someone stopped training (immobilization, bed-rest illness, or just skipping the gym) rather than which tissue is examined.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'loss_rate', 'A fully casted limb can lose about 3.5% of quadriceps cross-sectional area within 5 days and roughly 8% by two weeks.', 'cited_study', 'moderate', NULL, '{"pct_loss_5_days":3.5,"pct_loss_14_days":8}'::jsonb),
  ('detraining', 'loss_rate', 'An arm immobilized in a sling can lose about 20% of grip strength within just a few days, showing how fast true immobilization effects appear.', 'cited_study', 'moderate', NULL, '{"grip_strength_loss_pct":20,"timeframe":"a few days"}'::jsonb),
  ('detraining', 'loss_rate', 'Bed rest combined with a catabolic illness such as sepsis can be worse than immobilization alone, dropping muscle cross-sectional area by roughly 26% in one week.', 'cited_study', 'moderate', NULL, '{"pct_loss":26,"timeframe_days":7}'::jsonb),
  ('detraining', 'maintenance', 'Training the uninjured side or rest of the body while one limb is immobilized (cross-education) preserves some of that limb''s strength and size for a few weeks, though the effect fades with longer immobilization.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'loss_rate', 'Healthy people who simply stop training keep top-end strength for at least a couple weeks, show little loss in highly trained athletes after weeks off, and cap losses near 10% over two to three months.', 'cited_study', 'moderate', NULL, '{"pct_loss_cap":10,"timeframe":"2-3 months"}'::jsonb),
  ('detraining', 'loss_rate', 'Strength is lost roughly three times faster than muscle size during detraining (also seen in age-related sarcopenia); predicted decay order is strength, then size, then tendon, then bone.', 'mechanistic', 'hedged', NULL, '{"strength_to_size_loss_ratio":3}'::jsonb),
  ('detraining', 'retention', 'Rapid post-layoff strength return (''muscle memory'') is attributed to a combination of causes -- retained myonuclei reactivating, lingering neural/coordination adaptations, and epigenetic changes from prior training -- with no single mechanism fully explaining it.', 'mechanistic', 'hedged', NULL, NULL),
  ('detraining', 'return_prescription', 'A worked example for a 10-year lifter after a 2-month layoff kept the prior 4x/week frequency and lift skeleton, but rebuilt every working weight from an empty bar using feel rather than resuming old numbers.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'Return loads should be set using RPE 5-6 rather than a percentage of pre-layoff maxes, letting current capacity -- not history -- determine the actual working weight.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'Progression only advances once recovery checks pass: first raise effort (RPE 5-6 to 7) at the same volume, then add a set and push accessory RPE to 9 before moving reps back toward pre-layoff ranges.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'Movement patterns skipped during the layoff (e.g. a hinge pattern like the RDL that wasn''t trainable at home) get flagged for extra caution on return even for a long-tenured lifter.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'Full return to prior performance may take roughly as long as the layoff itself, though training something (even modified) during the break can shorten that recovery window.', 'experience', 'hedged', NULL, NULL),
  ('detraining', 'return_prescription', 'The named failure mode on return is chasing pre-layoff numbers or a training partner''s effort too soon; the resulting injury costs far more long-term time than a deliberately slow ramp back.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'soreness', 'The repeated bout effect gives protective benefit even from sessions that feel too easy, supporting a deliberately conservative start rather than skipping the easy early phase.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'by_training_age', 'Return programming is described as necessarily individualized -- driven by training age, whether any training occurred during the layoff, and ongoing self-reported recovery -- rather than one fixed timeline.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'loss_rate', 'Cited study: training 10 weeks then taking 3 months completely off caused a loss equivalent to about 5 weeks of the strength gained in that block, with non-significant size loss.', 'cited_study', 'moderate', NULL, '{"training_weeks":10,"layoff_weeks":13,"strength_lost_equiv_weeks":5}'::jsonb),
  ('detraining', 'loss_rate', 'Cited study: training 20 weeks then taking 30 weeks completely off led to about 13% strength loss and a comparably modest size decrease (presenter cautions against treating the number as precise).', 'cited_study', 'hedged', NULL, '{"training_weeks":20,"layoff_weeks":30,"strength_loss_pct":13}'::jsonb),
  ('detraining', 'retention', 'In that same 30-week-off study, just 6 weeks of retraining brought strength and size back above pre-layoff levels, showing rapid overshoot once training resumed.', 'cited_study', 'moderate', NULL, '{"retraining_weeks":6}'::jsonb),
  ('detraining', 'return_prescription', 'Exercise choice on return should weigh skill demand: compound lifts like the squat and deadlift require re-earning coordination on top of raw strength, unlike simple single-joint movements.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'soreness', 'Movements with heavy eccentric loading (RDLs, good mornings, split squats, deep lunges, slow-stretch flye-type moves) are singled out as disproportionately soreness-inducing on return and warrant extra caution.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'soreness', 'Trying a genuinely novel exercise or movement pattern causes soreness on its own, independent of underlying fitness or how much strength was actually lost.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'Early sessions back should stop short of pushing hard, since one overly sore session can impair the following week''s training -- described as doing just enough, then stopping.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'soreness', 'Recommends tracking soreness together with session RPE, sleep quality/quantity, and mood to guide progression, since soreness alone is an unreliable signal -- it can reflect novelty rather than real damage.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'Recommends a ''bridge'' strategy on return: pick rep ranges and exercise variations with little or no personal history (e.g., higher reps instead of near-max singles) so there''s no historical PR to compare against.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'Anecdote: after 8 months away from squat/bench/deadlift while training other movements instead, using the rep-range/variation bridge, strength returned to within about 10% of prior levels in roughly 6-8 weeks.', 'experience', 'hedged', NULL, '{"layoff_months":8,"weeks_to_within_10pct":"6-8"}'::jsonb),
  ('detraining', 'return_prescription', 'Framing a comeback around new PRs on unfamiliar variations, instead of the exact lifts and reps used before, works as both a psychological and physical on-ramp back into normal programming.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'illness', 'A patient on androgen deprivation therapy for prostate cancer (induced low testosterone) saw declining gym performance and was coached with the same reframing strategy -- new exercise variations to avoid pre-treatment comparisons.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'General principle: deliberately choosing exercises or rep schemes without a personal performance history removes the ego/comparison barrier that otherwise undermines adherence when returning to a prior training goal.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'Return-to-play progression should be governed by objective performance criteria rather than calendar time; pushing past unmet criteria reliably causes a setback cycle that takes longer than a patient, criteria-based approach.', 'experience', 'strong', NULL, NULL),
  ('detraining', 'return_prescription', 'Sport-specific reconditioning volume is recommended to start around 20-30% of a normal practice''s total time, then increase progressively week to week as tolerance is demonstrated.', 'experience', 'moderate', NULL, '{"starting_volume_pct":"20-30"}'::jsonb),
  ('detraining', 'soreness', 'Session-to-session swelling or stiffness after training is treated as a signal that the current load has hit the tissue''s present capacity, meaning load tolerance must be rebuilt before intensity increases further.', 'mechanistic', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'Most re-injuries after a comeback are attributed to two patterns: athletes who weren''t actually ready to return, and athletes who ramped activity intensity too fast without first building load tolerance.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', 'Cited figure: delaying full return past the traditional 6-month mark reduces reinjury risk by about 24% per additional month, with waiting to 9-10 months framed as a large cumulative risk reduction.', 'cited_study', 'moderate', NULL, '{"risk_reduction_pct_per_month":24,"reference_months":6,"target_months":"9-10"}'::jsonb),
  ('detraining', 'by_training_age', 'A teenager with no real training age should not be given a program built for athletes with years of training history, since training age -- not calendar age -- should set the programming ceiling.', 'experience', 'moderate', NULL, NULL),
  ('detraining', 'return_prescription', '''Medical clearance'' (imaging, tissue stability) and ''physical clearance'' (strength and functional testing) are treated as two distinct gates -- a doctor''s sign-off alone doesn''t mean an athlete is ready for full return.', 'experience', 'moderate', NULL, NULL),
  ('guideline', 'screening', 'ACSM''s 2015 preparticipation algorithm (Riebe et al., carried into ACSM''s Guidelines for Exercise Testing and Prescription) screens on three inputs: current exercise participation, known cardiovascular/metabolic/renal disease, and signs or symptoms.', 'guideline', 'moderate', NULL, NULL),
  ('guideline', 'screening', 'ACSM defines ''current exercise participation'' as planned, structured physical activity at least 30 min at moderate intensity on at least 3 days/week for at least the last 3 months.', 'guideline', 'moderate', NULL, '{"min_minutes_per_session":30,"min_days_per_week":3,"min_duration_months":3,"intensity":"moderate"}'::jsonb),
  ('guideline', 'screening', 'ACSM defines vigorous-intensity exercise, for algorithm purposes, as >=60% HRR or VO2R, >=6 METs, >=14 RPE -- an intensity causing substantial increases in heart rate and breathing.', 'guideline', 'moderate', NULL, '{"HRR_or_VO2R_pct_min":60,"METs_min":6,"RPE_min":14}'::jsonb),
  ('guideline', 'symptoms', 'ACSM''s signs/symptoms list gating clearance: chest/neck/jaw/arm pain possibly from ischemia; dyspnea at rest or mild exertion; dizziness/syncope; orthopnea/paroxysmal nocturnal dyspnea; ankle edema; palpitations/tachycardia; claudication; heart murmur; unusual fatigue.', 'guideline', 'moderate', NULL, NULL),
  ('guideline', 'screening', 'ACSM''s 2015 update eliminated cardiovascular risk-factor counting (e.g., hypertension, dyslipidemia) and the prior low/moderate/high risk-stratification categories, basing referral instead on diagnosed disease and current symptoms.', 'guideline', 'hedged', NULL, NULL),
  ('guideline', 'screening', 'ACSM''s algorithm sorts respondents into six classification cells (active/inactive x no-disease/disease-no-symptoms/symptomatic) to set clearance need, and applies to the ''general, nonclinical population'' rather than cardiac rehab settings.', 'guideline', 'hedged', NULL, NULL),
  ('guideline', 'clearance', 'ACSM algorithm: an inactive, asymptomatic adult with no diagnosed CV/metabolic/renal disease may begin light-to-moderate exercise without medical clearance.', 'guideline', 'hedged', NULL, NULL),
  ('guideline', 'clearance', 'ACSM algorithm: an inactive adult with diagnosed disease (even if asymptomatic), or anyone symptomatic regardless of history, should seek medical clearance before beginning exercise of any intensity.', 'guideline', 'hedged', NULL, NULL),
  ('guideline', 'clearance', 'ACSM algorithm: an adult already meeting the current-activity threshold who is asymptomatic with no diagnosed disease may continue moderate or vigorous exercise without medical clearance.', 'guideline', 'hedged', NULL, NULL),
  ('guideline', 'clearance', 'ACSM algorithm: an active adult with diagnosed disease but no symptoms may continue light-to-moderate exercise without clearance, but needs clearance before progressing to vigorous intensity.', 'guideline', 'hedged', NULL, NULL),
  ('guideline', 'screening', 'ACSM algorithm: sedentary, symptom-free individuals may begin exercise at light-to-moderate intensity without clearance, then increase beyond moderate ''following the principle of progression'' -- no specific duration/week figures given.', 'guideline', 'hedged', NULL, NULL),
  ('guideline', 'dose', 'ACSM (with CDC) recommends healthy adults 18-65 do moderate aerobic activity a minimum of 30 min on 5 days/week, OR vigorous aerobic activity a minimum of 20 min on 3 days/week.', 'guideline', 'strong', NULL, '{"moderate_min_minutes":30,"moderate_days_per_week":5,"vigorous_min_minutes":20,"vigorous_days_per_week":3,"age_range_years":"18-65"}'::jsonb),
  ('guideline', 'dose', 'ACSM recommends adults perform resistance exercise for the major muscle groups a minimum of 2 times per week to maintain or increase muscular strength and endurance.', 'guideline', 'strong', NULL, '{"min_days_per_week":2}'::jsonb),
  ('guideline', 'dose', 'ACSM''s general exercise guidance recommends flexibility exercise for the major muscle groups a minimum of 2 times per week.', 'guideline', 'moderate', NULL, '{"min_days_per_week":2}'::jsonb),
  ('guideline', 'dose', 'ACSM''s 2026 resistance training position stand (first major update since 2009) recommends lifting loads of 80% of one-repetition maximum for 2-3 sets per exercise for strength gains.', 'guideline', 'strong', NULL, '{"intensity_pct_1RM":80,"sets":"2-3"}'::jsonb),
  ('guideline', 'dose', 'ACSM''s 2026 resistance training guidance recommends roughly 10 sets per muscle group weekly, accumulated across sessions, for hypertrophy goals, training each major muscle group at least twice weekly.', 'guideline', 'strong', NULL, '{"sets_per_muscle_group_per_week":"~10","min_days_per_week":2}'::jsonb),
  ('guideline', 'dose', 'ACSM''s 2026 resistance training guidance recommends moderate loads (30-70% of 1RM) moved with maximal intended concentric velocity for power development.', 'guideline', 'strong', NULL, '{"intensity_pct_1RM":"30-70"}'::jsonb),
  ('guideline', 'stages', 'NSCA LTAD position stand: early childhood training should prioritize motor skill development and foundational muscular strength as synergistic components, not separate qualities, exploiting peak neural plasticity for motor learning.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'stages', 'NSCA LTAD position stand: children may begin structured resistance training around age 6-7 once emotionally mature enough to follow directions and control balance/posture; ages 0-6 emphasize exploratory play.', 'guideline', 'moderate', NULL, '{"start_age_years":"6-7","play_age_range_years":"0-6"}'::jsonb),
  ('guideline', 'stages', 'NSCA LTAD position stand: readiness for organized sport is the practical gate for starting strength and conditioning — if a child is ready for organized sport, they are ready for it.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'stages', 'NSCA LTAD position stand explicitly challenges Balyi''s ''windows of opportunity'' trainability model, citing insufficient longitudinal evidence; both children and adolescents can improve all fitness components at any developmental stage.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'maturity', 'NSCA LTAD position stand: training age/maturity, not chronology, should drive exercise-mode selection — pre-PHV youth gain more from plyometric training alone; post-PHV youth respond better to combined strength+plyometric training.', 'guideline', 'moderate', NULL, NULL),
  ('guideline', 'maturity', 'NSCA LTAD position stand recommends quarterly assessment of stature, limb length, and body mass (not chronological age) to track growth curves and flag youth at risk of growth-related injury.', 'guideline', 'strong', NULL, '{"assessment_frequency":"quarterly"}'::jsonb),
  ('guideline', 'maturity', 'NSCA LTAD position stand: injury risk, especially lower-limb, peaks during the adolescent growth spurt because bone growth outpaces muscle/tendon and strength/power adaptation, creating a maturity-linked risk window independent of age.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'maturity', 'NSCA LTAD position stand cautions that early talent-identification/selection processes systematically favor early-maturing youth and exclude later maturers, and that predictive success rates to elite adult sport are questionable.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'specialisation', 'NSCA LTAD position stand defines early sport specialization as year-round intensive single-sport training excluding other activities; links it to higher injury risk, blunted motor skills, and reduced later-life performance.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'specialisation', 'NSCA LTAD position stand: youth should not train more than 8 months per year in a single sport; weekly training volume exceeding 16 hours marks a threshold above which injury risk increases.', 'guideline', 'strong', NULL, '{"max_months_per_year_single_sport":8,"weekly_training_hours_injury_threshold":16}'::jsonb),
  ('guideline', 'specialisation', 'NSCA LTAD position stand: a sampling (multi-sport) approach does not impair elite development; youth playing 3+ sports at ages 11-15 were more likely to reach national- vs club-level play at 16-18.', 'guideline', 'strong', NULL, '{"sports_count_threshold":"3+","sampling_age_range":"11-15","outcome_age_range":"16-18"}'::jsonb),
  ('guideline', 'specialisation', 'NSCA LTAD position stand cites data showing early-specialized female youth athletes face 1.5x greater knee-injury risk and 4x greater risk of patellar tendinopathy/Osgood-Schlatter disease versus multi-sport peers.', 'guideline', 'strong', NULL, '{"knee_injury_relative_risk":1.5,"patellar_tendinopathy_relative_risk":4}'::jsonb),
  ('guideline', 'cautions', 'NSCA LTAD position stand cites heightened injury risk when weekly sport-practice hours exceed a youth''s age in years, or when organized-sport-to-free-play time ratio exceeds 2:1.', 'guideline', 'strong', NULL, '{"practice_hours_vs_age_rule":"hours/week > age in years","organized_to_free_play_ratio_threshold":"2:1"}'::jsonb),
  ('guideline', 'cautions', 'NSCA LTAD position stand explicitly rejects the ''10,000-hour deliberate practice rule'' as a basis for youth training prescription, instructing practitioners to value quality of practice over quantity.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'cautions', 'NSCA LTAD position stand recommends at least 48 hours rest before competition and 7+ hours nightly sleep; flags competitions lasting 6+ hours with insufficient rest as an injury risk factor.', 'guideline', 'strong', NULL, '{"pre_competition_rest_hours":48,"min_sleep_hours":7,"long_competition_risk_hours":6}'::jsonb),
  ('guideline', 'cautions', 'NSCA LTAD position stand lists overtraining warning signs to monitor: appetite loss, more frequent injuries/tiredness/respiratory infections, inability to cope with training load, heavy/stiff muscles, and disrupted sleep.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'strength', 'NSCA LTAD position stand: well-rounded strength and conditioning (resistance training + motor skill/balance + speed/agility + adequate rest) can reduce youth injury incidence by as much as 50%.', 'guideline', 'strong', NULL, '{"injury_reduction_pct":50}'::jsonb),
  ('guideline', 'strength', 'NSCA LTAD position stand cites a meta-analysis of 34 studies: pre- and early-pubertal youth show resistance-training-induced motor-skill gains approximately 50% greater than adolescents, indicating higher motor-skill trainability when younger.', 'guideline', 'moderate', NULL, '{"motor_skill_gain_relative_pct":50,"studies_in_meta_analysis":34}'::jsonb),
  ('guideline', 'progression', 'NSCA LTAD position stand: practitioners should prescribe rest/recovery as mandatory, non-negotiable blocks within youth periodized plans, irrespective of coach or parent pressure, especially for multi-team/multi-sport athletes.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'progression', 'NSCA LTAD position stand: young children''s programs should emphasize general preparatory training (fundamental movement skills, foundational strength); sport-specific practice time should increase only as the child grows older.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'progression', 'NSCA LTAD position stand: during growth spurts, youth may show temporary motor-control disruption (''adolescent awkwardness''); practitioners should reduce training loads and modify patterns rather than follow a fixed progression schedule.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'clearance', 'Bern 2016 consensus (Ardern et al.): RTS decision should be shared among athlete, clinician(s), and coach(es), except when the clinician must unilaterally remove the athlete for immediate health protection.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'clearance', 'Bern 2016 consensus: RTS is a continuum of three stages — return to participation, return to sport, return to performance — not a single decision at rehab''s end.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'clearance', 'Panther Symposium ACL RTS consensus (26/26 unanimous): purely time-based return-to-sport decision-making after ACL injury should be abandoned in favor of criteria-based progression through defined phases.', 'guideline', 'strong', NULL, '{"agreement":"26/26"}'::jsonb),
  ('guideline', 'clearance', 'Panther Symposium consensus (25/26, 96%): the health care provider alone should make the initial decision to progress an ACL-reconstructed athlete to unrestricted training.', 'guideline', 'strong', NULL, '{"agreement":"25/26 (96%)"}'::jsonb),
  ('guideline', 'clearance', 'Panther Symposium consensus: clearance to full sport participation after ACL reconstruction should be a multidisciplinary decision — patient, parent if under 18, surgeon, team physician, and PT/athletic trainer (26/26).', 'guideline', 'strong', NULL, '{"agreement":"26/26"}'::jsonb),
  ('guideline', 'clearance', 'Panther Symposium consensus: RTS before 6 months post-ACL-reconstruction likely represents unacceptably high reinjury risk due to graft maturation, even within a criteria-based decision framework.', 'guideline', 'strong', NULL, '{"minimum_months":6}'::jsonb),
  ('guideline', 'clearance', 'van Melick/KNGF ACL guideline (BJSM 2016): rehabilitation should shift from time-based to goal-based, criterion-based progression — athletes advance phases only when prior-phase goals are confirmed by objective tests.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'criteria', 'Bern 2016 consensus: for Achilles tendon rupture, no milestone-based RTS criteria exist in the literature; guidance is purely time-based — noncontact sport at 16 weeks, contact sport at 20 weeks post-injury.', 'guideline', 'strong', NULL, '{"noncontact_weeks":16,"contact_weeks":20}'::jsonb),
  ('guideline', 'criteria', 'Bern 2016 consensus: before RTS clearance, Achilles tendinopathy pain during activity should not exceed 5/10, must subside by the next morning, and must not worsen week to week.', 'guideline', 'strong', NULL, '{"max_pain_nrs":"5/10"}'::jsonb),
  ('guideline', 'criteria', 'van Melick/KNGF ACL guideline: an LSI (limb symmetry index) >90% across a strength-and-hop test battery is suggested as RTS cutoff; ~100% recommended for pivoting/contact sports (Level 3 evidence, cutoff uncertain).', 'guideline', 'hedged', NULL, '{"lsi_cutoff_general":">90%","lsi_cutoff_pivoting_contact":"~100%"}'::jsonb),
  ('guideline', 'criteria', 'van Melick/KNGF ACL guideline: applying a 90% LSI cutoff across six strength/hop tests, only 23% of ACLR patients passed; at a 95% LSI cutoff, only 10% passed (cited cohort study).', 'guideline', 'moderate', NULL, '{"pass_rate_at_90pct_LSI":"23%","pass_rate_at_95pct_LSI":"10%"}'::jsonb),
  ('guideline', 'criteria', 'van Melick/KNGF ACL guideline: a preoperative quadriceps strength deficit greater than 20% versus the uninjured leg predicts significantly worse self-reported knee function at 2-year follow-up after ACL reconstruction.', 'guideline', 'strong', NULL, '{"preop_quad_deficit_threshold":">20%"}'::jsonb),
  ('guideline', 'criteria', 'Panther Symposium consensus: the Delaware-Oslo criteria-based RTS test battery (isometric quad strength, 4 single-leg jump tests, 2 patient-reported outcomes, each at a 90% threshold) predicted over 6-fold lower reinjury risk.', 'guideline', 'strong', NULL, '{"threshold":"90%","reinjury_risk_reduction":">6x lower"}'::jsonb),
  ('guideline', 'criteria', 'Panther Symposium consensus (cited study): quadriceps strength symmetry below 90% was associated with 33% reinjury after ACL reconstruction, versus 13% reinjury when quadriceps symmetry exceeded 90%.', 'guideline', 'moderate', NULL, '{"reinjury_lt_90pct_symmetry":"33%","reinjury_gt_90pct_symmetry":"13%"}'::jsonb),
  ('guideline', 'criteria', 'Panther Symposium consensus (cited study): each 1-percentage-point increase in quadriceps limb symmetry index was associated with a 3% reduction in subsequent knee injury risk after ACL reconstruction.', 'guideline', 'moderate', NULL, '{"per_1pct_LSI_increase":"3% risk reduction"}'::jsonb),
  ('guideline', 'criteria', 'Bern 2016 consensus: for acute hamstring injury, no validated objective RTS criteria exist; proposed (unvalidated) markers include pain-free exam, minimal ROM/strength deficit, symmetric hop performance, and preinjury sprint speed.', 'guideline', 'hedged', NULL, NULL),
  ('guideline', 'criteria', 'Bern 2016 consensus: for groin injury, reduced hip adduction strength is linked to adductor injury risk; the guideline suggests measuring it to inform RTS but states no numeric cutoff.', 'guideline', 'hedged', NULL, NULL),
  ('guideline', 'criteria', 'AOPT/JOSPT Achilles tendinopathy CPG: clinicians should document VISA-A score, FAAM or LEFS, and hop/heel-raise endurance test results, but the guideline gives no explicit numeric pass/fail threshold for RTS clearance.', 'guideline', 'hedged', NULL, NULL),
  ('guideline', 'criteria', 'Bern 2016 consensus: shoulder RTS guidance suggests targeting roughly 10% greater rotator cuff strength on the throwing side versus the non-throwing side, with external/internal rotation ratios of 65%-100%.', 'guideline', 'hedged', NULL, '{"rotator_cuff_strength_target":"~10% greater on throwing side","er_ir_ratio_isokinetic":"65%","er_ir_ratio_isometric":"100%"}'::jsonb),
  ('guideline', 'load_reintroduction', 'Bern 2016 consensus: the acute:chronic workload ratio (current week''s load vs. prior 4-week average) is proposed as a tool for planning load progression through the RTS continuum; untested in rehab.', 'guideline', 'hedged', NULL, NULL),
  ('guideline', 'load_reintroduction', 'Bern 2016 consensus (''Goldilocks approach''): achieving and maintaining optimal loading — neither too much nor too little tissue stress — is described as a key consideration in RTS load progression.', 'guideline', 'moderate', NULL, NULL),
  ('guideline', 'load_reintroduction', 'van Melick/KNGF ACL guideline: postoperative rehabilitation should continue 9-12 months through 3 criterion-based phases (impairment-based, sport-specific training, return to play), each requiring prior-phase goals before progressing.', 'guideline', 'strong', NULL, '{"duration_months":"9-12"}'::jsonb),
  ('guideline', 'load_reintroduction', 'van Melick/KNGF ACL guideline: closed-chain quad exercise may start week 2 post-op; open-chain exercise from week 4 in restricted 90 deg-45 deg ROM, progressively opened to full ROM by week 8.', 'guideline', 'strong', NULL, '{"ckc_start_week":2,"okc_start_week":4,"full_rom_by_week":8}'::jsonb),
  ('guideline', 'load_reintroduction', 'Bern 2016 consensus: Achilles tendinopathy patients who follow a standardized, progressive loading program have fewer recurrences after RTS than those who do not follow a progressive-loading protocol.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'load_reintroduction', 'AOPT/JOSPT Achilles tendinopathy CPG (Grade A): clinicians should use tendon-loading exercise, with loads as high as tolerated, as first-line treatment for midportion Achilles tendinopathy.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'load_reintroduction', 'AOPT/JOSPT low back pain CPG (Grade A): should use exercise training — trunk strengthening/endurance, multimodal, or general exercise — for chronic LBP; benefit tied to appropriate volume/intensity and progressive overload, not exercise type.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'load_reintroduction', 'AOPT/JOSPT low back pain CPG: exercise training for acute LBP is only a Grade C (''can use'') recommendation — markedly weaker evidence than the Grade A recommendation for chronic LBP.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'load_reintroduction', 'AOPT/JOSPT low back pain CPG (Grade C): clinicians can use general exercise training for postoperative LBP after lumbar spine surgery; Grade B — may give general education on resuming activity.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'scope', 'Panther Symposium consensus: including the coach as a formal ACL return-to-sport decision-maker did not reach consensus (7/26, 27% agreement) due to conflict-of-interest concerns; decision reserved to medical/PT team plus patient/parent.', 'guideline', 'strong', NULL, '{"agreement":"7/26 (27%)"}'::jsonb),
  ('guideline', 'scope', 'Bern 2016 consensus: in some jurisdictions clinicians are legally required to act unilaterally to remove an athlete from sport when necessary to protect health, overriding shared decision-making with athlete/coach.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'scope', 'AOPT/JOSPT low back pain CPG (2021): this guideline deliberately excludes red-flag screening and differential diagnosis from its scope, stating those topics are ''well covered in other guidelines'' — no red-flag criteria given here.', 'guideline', 'hedged', NULL, NULL),
  ('guideline', 'scope', 'Bern 2016 consensus, citing prior work: a 2002 US multi-society expert panel named the team physician as sole ''gatekeeper'' of the RTS decision; the 2016 consensus instead favors shared, athlete-centered decision-making.', 'guideline', 'moderate', NULL, NULL),
  ('guideline', 'working_around', 'Bern 2016 consensus: an RTS decision may reverse to ''removal from sport'' when symptoms worsen; this need not mean stopping all participation but modifying training/competition load instead.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'working_around', 'Bern 2016 consensus: reducing an athlete''s load or removing them from sport requires the athlete, coach(es), and clinician(s) to decide together — except when clinicians are legally required to act alone.', 'guideline', 'strong', NULL, NULL),
  ('guideline', 'working_around', 'Bern 2016 consensus: ''return to participation'' describes training or competing below one''s target level while not yet medically, physically, or psychologically ready — training capacity alone does not equal RTS readiness.', 'guideline', 'moderate', NULL, NULL);
